vector<string> split(const string& str, const string& delimiter) {
    vector<string> result;
    size_t start = 0;
    size_t end = str.find(delimiter);
    while (end != string::npos) {
        result.push_back(str.substr(start, end - start));
        start = end + delimiter.length();
        end = str.find(delimiter, start);
    }
    // 添加最后一个部分
    result.push_back(str.substr(start));
    return result;
}

 // kmp 算法求next数组
vector<int> getNext(vector<string> ans) {
    int n = ans.size();
    vector<int> next(n, 0);
    for (int i = 1; i < n; i++) {
        int j = next[i - 1];
        while (j > 0 && ans[i] != ans[j]) {
            j = next[j-1];
        }
        if (ans[i] == ans[j]) {
            j += 1;
        }
        next[i] = j;
    }
    return next;
}
​
int main() {
    int n;
    cin >> n;
    vector<string> ans(n);
    for (int i = 0; i < n; i++) {
        cin >> ans[i];
    }
    vector<int> next = getNext(ans);
    int prefixLen = next[n - 1];
    // 是由部分子数重复循环拼接组成
    if (prefixLen > 0 && (n % (n - prefixLen) == 0)) {
        for (int i = 0; i < n - prefixLen; i++) {
            cout << ans[i];
            if (i != n - prefixLen - 1) {
                cout << " ";
            }
        }
    // 就是本身    
    } else {
        for (int i = 0; i < n; i++) {
            cout << ans[i];
            if (i != n - 1) {
                cout << " ";
            }
        }
    }
    return 0;
 }
