    // 构建 KMP 的 next 数组
    public static int[] getNext(List<String> ans) {
        int n = ans.size();
        int[] next = new int[n];
        for (int i = 1; i < n; i++) {
            int j = next[i - 1];
            while (j > 0 && !ans.get(i).equals(ans.get(j))) {
                j = next[j - 1];
            }
            if (ans.get(i).equals(ans.get(j))) {
                j++;
            }
            next[i] = j;
        }
        return next;
    }
