package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strings"
)
​
// 构建 KMP 的 next 数组
func getNext(ans []string) []int {
    n := len(ans)
    next := make([]int, n)
    for i := 1; i < n; i++ {
        j := next[i-1]
        for j > 0 && ans[i] != ans[j] {
            j = next[j-1]
        }
        if ans[i] == ans[j] {
            j++
        }
        next[i] = j
    }
    return next
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    var n int
    fmt.Sscanf(scanner.Text(), "%d", &n)
​
    scanner.Scan()
    ans := strings.Fields(scanner.Text())
​
    next := getNext(ans)
    prefixLen := next[n-1]
​
    if prefixLen > 0 && n%(n-prefixLen) == 0 {
        fmt.Print(strings.Join(ans[:n-prefixLen], " "))
    } else {
        fmt.Print(strings.Join(ans, " "))
    }
}
